/** Runs spec/conformance.json: results generated by the reference (Python) implementation. */
import { describe, expect, it } from 'vitest';
import conformance from '../spec/conformance.json';
import * as kh from '../src/index';
import { levelOf } from '../src/core';

interface Case {
  fn: string;
  args: unknown[];
  kwargs: Record<string, unknown>;
  expect?: unknown;
  expect_len?: number;
  raises?: string;
}

/* eslint-disable @typescript-eslint/no-explicit-any */
type Caller = (args: any[], kw: Record<string, any>) => unknown;
const CALL: Record<string, Caller> = {
  provinces: () => kh.provinces(),
  districts: ([p]) => kh.districts(p),
  communes: ([p, d]) => kh.communes(p, d),
  villages: ([p, d, c]) => kh.villages(p, d, c),
  get_province: ([q]) => kh.getProvince(q),
  get_district: ([q], k) => kh.getDistrict(q, { province: k.province }),
  get_commune: ([q], k) => kh.getCommune(q, { district: k.district, province: k.province }),
  get_village: ([q], k) => kh.getVillage(q, { commune: k.commune, district: k.district, province: k.province }),
  search: ([q], k) => kh.search(q, { level: k.level, limit: 'limit' in k ? k.limit : undefined }),
};

function plain(value: any, withLevel: boolean): unknown {
  if (value === null) return null;
  if (Array.isArray(value)) return value.map((v) => plain(v, withLevel));
  return withLevel ? { level: levelOf(value), ...kh.toDict(value) } : kh.toDict(value);
}

describe('conformance with the reference implementation', () => {
  it('was generated from the same data year', () => {
    expect(conformance.data_year).toBe(kh.DATA_YEAR);
  });

  for (const c of conformance.cases as Case[]) {
    const title = `${c.fn}(${JSON.stringify(c.args)}, ${JSON.stringify(c.kwargs)})`;
    it(title, () => {
      const call = () => CALL[c.fn](c.args, c.kwargs);
      if (c.raises) {
        expect(call).toThrow(RangeError);
        return;
      }
      const actual = plain(call(), c.fn === 'search');
      if (c.expect_len !== undefined) expect((actual as unknown[]).length).toBe(c.expect_len);
      else expect(actual).toEqual(c.expect);
    });
  }
});
